  "If your account needs verification, a new link will arrive in your inbox.": {"ckb": "ئەگەر هەژمارەکەت پێویستی بە پشتڕاستکردنەوە بێت، بەستەرێکی نوێ دێتە سندوقی نامەکانت.", "kmr": "ئەگەر هەژمارا تە پێدڤی ب پشتڕاستکرنێ هەبیت، لینکەکا نوی دێ گەهیتە سندوقا نامەیێن تە.", "ar": "إذا كان حسابك بحاجة إلى التحقق، فسيصلك رابط جديد إلى بريدك."},
  "Resend verification email": {"ckb": "ئیمەیڵی پشتڕاستکردنەوە دووبارە بنێرە", "kmr": "ئیمەیلا پشتڕاستکرنێ دووبارە بهنێرە", "ar": "إعادة إرسال رسالة التحقق"},
  "Too many email requests. Please wait a few minutes before trying again.": {"ckb": "داواکاریی ئیمەیڵ زۆرە. تکایە چەند خولەکێک چاوەڕێ بکە و پاشان دووبارە هەوڵ بدە.", "kmr": "داخوازیێن ئیمەیلێ زۆرن. هیڤییە چەند خولەکان چاڤەڕێ بە و پاشی دووبارە هەول بدە.", "ar": "طلبات البريد كثيرة. انتظر بضع دقائق قبل المحاولة مجددًا."},
  "Email delivery is currently unavailable. Please contact support.": {"ckb": "ناردنی ئیمەیڵ لە ئێستادا بەردەست نییە. تکایە پەیوەندی بە پشتگیرییەوە بکە.", "kmr": "هنارتنا ئیمەیلێ نوکە بەردەست نینە. هیڤییە پەیوەندیێ ب پشتەڤانیێ بکە.", "ar": "إرسال البريد الإلكتروني غير متاح حاليًا. يرجى التواصل مع الدعم."},
  "Could not send the email. Check your connection and try again.": {"ckb": "ئیمەیڵەکە نەنێردرا. پەیوەندی ئینتەرنێتەکەت بپشکنە و دووبارە هەوڵ بدە.", "kmr": "ئیمەیل نەهاتە هنارتن. پەیوەندییا ئینتەرنێتێ بپشکنە و دووبارە هەول بدە.", "ar": "تعذر إرسال البريد. تحقق من اتصالك وحاول مجددًا."},
  "Iraq time (UTC+3)": {"ckb": "بە کاتی عێراق (UTC+3)", "kmr": "ب دەمێ عێراقێ (UTC+3)", "ar": "بتوقيت العراق (UTC+3)"},
  "View court": {"ckb": "یاریگا ببینە", "kmr": "یاریگەهێ ببینە", "ar": "عرض الملعب"},
