  "Find a court and send your first booking request.": {"ckb": "یاریگایەک بدۆزەوە و یەکەم داواکاریی حجزت بنێرە.", "kmr": "یاریگەهەکێ ببینە و ئێکەم داخوازییا حجزا خو بهنێرە.", "ar": "اعثر على ملعب وأرسل طلب حجزك الأول."},
  "Invalid refund amount": {"ckb": "بڕی گەڕاندنەوەی پارە نادروستە", "kmr": "بڕێ ڤەگەڕاندنا پارەی نەدروستە", "ar": "مبلغ الاسترداد غير صالح"},
