  "Your approved booking details are shown below.": {"ar": "تفاصيل حجزك الموافق عليه موضحة أدناه.", "ckb": "وردەکاریی حجزە پەسەندکراوەکەت لە خوارەوە پیشان دراون.", "kmr": "وردەکاریێن حجزا تە یا پەسەندکری ل خوارێ دهێنە نیشاندان."},
  "Booking completed": {"ar": "اكتمل الحجز", "ckb": "حجزەکە تەواو بوو", "kmr": "حجز تەمام بوو"},
  "Booking cancelled": {"ar": "تم إلغاء الحجز", "ckb": "حجزەکە هەڵوەشێندرایەوە", "kmr": "حجز هاتە هەلوەشاندن"},
  "This booking has been cancelled.": {"ar": "تم إلغاء هذا الحجز.", "ckb": "ئەم حجزە هەڵوەشێندراوەتەوە.", "kmr": "ئەڤ حجزە هاتییە هەلوەشاندن."},
  "Booking request expired": {"ar": "انتهت صلاحية طلب الحجز", "ckb": "ماوەی داواکاریی حجزەکە بەسەرچوو", "kmr": "دەمێ داخوازییا حجزێ ب دوماهیک هات"},
