  "REFUND DEBT": { ar: "دين الاسترداد", ckb: "قەرزی گەڕاندنەوە", kmr: "قەرزێ ڤەگەڕاندنێ" },
  "100% Retention Policy:": { ar: "سياسة الاحتفاظ بنسبة 100٪:", ckb: "سیاسەتی هێشتنەوەی ١٠٠٪:", kmr: "سیاسەتا هێشتنەوەیا ١٠٠٪:" },
  "Are you sure you want to block this listing? This will prevent it from being visible to guests.": { ar: "هل أنت متأكد من حظر هذا الملعب؟ لن يظهر للاعبين بعد الحظر.", ckb: "دڵنیایت دەتەوێت ئەم یاریگایە بلۆک بکەیت؟ بۆ یاریزانان دیار نابێت.", kmr: "تو پشتڕاستی دڤێت ڤێ یاریگەهێ بلۆک بکەی؟ بۆ یاریزانان دیار نابیت." },
  "Are you sure you want to delete this FAQ? This action cannot be undone.": { ar: "هل أنت متأكد من حذف هذا السؤال؟ لا يمكن التراجع عن هذا الإجراء.", ckb: "دڵنیایت لە سڕینەوەی ئەم پرسیارە؟ ئەم کردارە ناگەڕێتەوە.", kmr: "تو پشتڕاستی ژێبرنا ڤی پرسیاری؟ ئەڤ کردار ناهێتە ڤەگەڕاندن." },
  "Are you sure you want to mark this payout as completed? This action confirms that the payment has been successfully processed and sent to the host.": { ar: "هل تريد تحديد هذه الدفعة كمكتملة؟ هذا يؤكد إرسالها بنجاح إلى صاحب الملعب.", ckb: "دڵنیایت ئەم پارەدانە وەک تەواوکراو دیاری بکەیت؟ ئەمە ناردنی پارە بۆ خاوەن یاریگا پشتڕاست دەکاتەوە.", kmr: "تو پشتڕاستی ڤێ دانە پارەیێ وەک تەمامکری دیار بکەی؟ ئەڤە هنارتنا پارەی بۆ خودانێ یاریگەهێ پشتڕاست دکەت." },
  "Host payout": { ar: "دفعة صاحب الملعب", ckb: "پارەدانی خاوەن یاریگا", kmr: "دانە پارەیا خودانێ یاریگەهێ" },
  "Total (guest pays)": { ar: "الإجمالي الذي يدفعه اللاعب", ckb: "کۆی پارەی یاریزان", kmr: "کۆیا پارەیێ یاریزانی" },
  "This will:": { ar: "سيؤدي هذا إلى:", ckb: "ئەمە دەبێتە هۆی:", kmr: "ئەڤە دێ بیتە ئەگەرێ:" },
  "This income is from a dispute resolved in the host's favor.": { ar: "هذا الدخل ناتج عن نزاع حُسم لصالح صاحب الملعب.", ckb: "ئەم داهاتە لە ناکۆکییەکەوەیە کە بە قازانجی خاوەن یاریگا چارەسەر کراوە.", kmr: "ئەڤ داهاتە ژ ناکۆکییەکێ یە کو ب قازانجا خودانێ یاریگەهێ هاتیە چارەسەرکرن." },
  "This represents a refund issued to the guest. This amount will be deducted from the host's next payout for this booking.": { ar: "يمثل هذا المبلغ استردادًا للاعب، وسيُخصم من الدفعة التالية لصاحب الملعب.", ckb: "ئەمە پارەیەکی گەڕێندراوە بۆ یاریزان و لە پارەدانی داهاتووی خاوەن یاریگا کەم دەکرێتەوە.", kmr: "ئەڤە پارەیەکا ڤەگەڕاندی بۆ یاریزانییە و ژ دانە پارەیا داهاتی یا خودانێ یاریگەهێ دێ کێم بیت." },
  "This payout was fully offset by outstanding guest debts. No payment will be made.": { ar: "تمت تسوية هذه الدفعة بالكامل مقابل ديون اللاعب، ولن يتم إرسال دفعة.", ckb: "ئەم پارەدانە بە تەواوی بە قەرزی یاریزان یەکسان کرایەوە و هیچ پارەیەک نانێردرێت.", kmr: "ئەڤ دانە پارەیە ب تەمامی ب قەرزێ یاریزانی هاتە یەکسانکرن و چ پارە ناهێتە هنارتن." },
  "This payout will be processed once the guest pays their outstanding debt.": { ar: "ستُعالج هذه الدفعة بعد سداد اللاعب للدين المستحق.", ckb: "ئەم پارەدانە دوای دانی قەرزی یاریزان جێبەجێ دەکرێت.", kmr: "ئەڤ دانە پارەیە پشتی دانا قەرزێ یاریزانی دێ بهێتە پڕۆسەکرن." },
  "The cancellation policy for this booking allowed 0% refund to the guest. Host receives the full retained amount after platform commission.": { ar: "سياسة الإلغاء لهذا الحجز لا تسمح باسترداد للاعب. يحصل صاحب الملعب على المبلغ المحتفظ به بعد خصم عمولة المنصة.", ckb: "سیاسەتی هەڵوەشاندنەوەی ئەم رزێرڤە گەڕاندنەوەی پارە ڕێگەپێنادات. خاوەن یاریگا دوای کۆمیسیۆن بڕەکە وەردەگرێت.", kmr: "سیاسەتا هەلوەشاندنا ڤێ حجزێ ڤەگەڕاندنا پارەی نادات. خودانێ یاریگەهێ پشتی کۆمیسیۆنێ بڕی وەردگریت." },
  "The cancellation policy for this booking allowed 0% refund to the guest. You receive the full retained amount after platform commission.": { ar: "سياسة الإلغاء لهذا الحجز لا تسمح باسترداد للاعب. تحصل على المبلغ المحتفظ به بعد خصم عمولة المنصة.", ckb: "سیاسەتی هەڵوەشاندنەوەی ئەم رزێرڤە گەڕاندنەوەی پارە ڕێگەپێنادات. دوای کۆمیسیۆن بڕەکە وەردەگریت.", kmr: "سیاسەتا هەلوەشاندنا ڤێ حجزێ ڤەگەڕاندنا پارەی نادات. پشتی کۆمیسیۆنێ بڕی وەردگری." },
