  "This court is ready for its first verified player review.": { ckb: "ئەم یاریگایە ئامادەی یەکەم هەڵسەنگاندنی پشتڕاستکراوەی یاریزانە.", kmr: "ئەڤ یاریگەه بۆ ئێکەم هەلسەنگاندنا پشتڕاستکری یا یاریزانێ ئامادەیە.", ar: "هذا الملعب جاهز لاستقبال أول تقييم موثّق من لاعب." },
  "Show all reviews": { ckb: "هەموو هەڵسەنگاندنەکان پیشان بدە", kmr: "هەمی هەلسەنگاندنان نیشان بدە", ar: "عرض جميع التقييمات" },
  "Ball rental": { ckb: "بەکرێدانی تۆپ", kmr: "کرێکرنا توپێ", ar: "تأجير الكرة" },
  "Premium indoor padel court with glass walls and pro lighting. Racket rental available at reception.": { ckb: "یاریگای پادێلی ناوخۆیی نایاب بە دیواری شووشەیی و ڕووناکی پیشەیی. بەکرێدانی ڕاکێت لە پێشوازیکردن بەردەستە.", kmr: "یاریگەها پادێلا ناڤخۆ یا تایبەت ب دیوارێن شووشەیی و ڕوناهییا پیشەیی. کرێکرنا راکێتێ ل پێشوازیێ بەردەستە.", ar: "ملعب بادل داخلي مميز بجدران زجاجية وإضاءة احترافية. تتوفر مضارب للإيجار عند الاستقبال." },
  "Floodlit artificial turf pitch in central Stockholm. Perfect for 5-a-side evening games with changing rooms and showers on site.": { ckb: "یاریگای چیمەنی دەستکرد و ڕووناککراوە لە ناوەندی ستۆکهۆڵم. گونجاوە بۆ یارییە شەوانەکانی 5 بەرامبەر 5، لەگەڵ ژووری گۆڕینی جل و دووش.", kmr: "یاریگەها گیایا دەستکرد و ڕوناککری ل ناڤەندا ستۆکهۆلمێ. گونجایە بۆ یاریێن شەڤێ 5 دژی 5، لگەل ژوورێن گوهارتنا جل و دووشێ.", ar: "ملعب عشب صناعي مضاء في وسط ستوكهولم، مثالي لمباريات الخماسي المسائية، مع غرف تبديل ملابس ودُش في الموقع." },
  "Indoor shoes only.": { ckb: "تەنها پێڵاوی ناوخۆ.", kmr: "تنێ پێلاڤێن ناڤخۆ.", ar: "أحذية داخلية فقط." },
  "No metal studs. Clean up after your game.": { ckb: "قۆناغی کانزایی قەدەغەیە. دوای یارییەکەت شوێنەکە پاک بکەرەوە.", kmr: "میخێن کانزایی قەدەغەنە. پشتی یاریا خۆ جهی پاک بکە.", ar: "يُمنع ارتداء الأحذية ذات المسامير المعدنية. يرجى تنظيف المكان بعد المباراة." },
  "Full refund if cancelled at least 1 day before your slot.": { ckb: "ئەگەر لانیکەم ڕۆژێک پێش کاتەکەت هەڵبوەشێنیتەوە، هەموو پارەکەت دەگەڕێتەوە.", kmr: "ئەگەر کێمترین ڕۆژەکێ بەری دەما خۆ هەلوەشینی، هەمی پارە دێ زڤڕیت.", ar: "استرداد كامل عند الإلغاء قبل الموعد بيوم واحد على الأقل." },
  "Great pitch, lights were perfect and the changing rooms were clean. Will book again.": { ckb: "یاریگایەکی زۆر باش، ڕووناکییەکان ناوازە بوون و ژوورەکانی گۆڕینی جل پاک بوون. دووبارە رزێرڤی دەکەمەوە.", kmr: "یاریگەهەکا زۆر باش، ڕوناهی تەمام بوو و ژوورێن گوهارتنا جل پاک بوون. دێ دیسان حجز کەم.", ar: "ملعب رائع، كانت الإضاءة ممتازة وغرف تبديل الملابس نظيفة. سأحجزه مرة أخرى." },
  "Select play date": { ckb: "بەرواری یاری هەڵبژێرە", kmr: "ڕۆژا یاریێ هەلبژێرە", ar: "اختر تاريخ اللعب" },
