  "Loading page": { ckb: "پەڕەکە بار دەکرێت", kmr: "پەڕە دهێتە بارکرن", ar: "جارٍ تحميل الصفحة" },
  "Your court was submitted for review. It will appear in search as soon as an admin approves it.": { ckb: "یاریگاکەت بۆ پێداچوونەوە نێردرا. هەر کە بەڕێوەبەر پەسەندی بکات لە گەڕاندا دەردەکەوێت.", kmr: "یاریگەها تە بۆ پێداچوونێ هاتە هنارتن. دەمێ بەڕێڤەبەر پەسەند بکەت دێ ل لێگەڕیانێ دیار بیت.", ar: "تم إرسال ملعبك للمراجعة، وسيظهر في البحث فور موافقة المسؤول عليه." },
  "Listing approved and is now available in search": { ckb: "یاریگاکە پەسەند کرا و ئێستا لە گەڕاندا بەردەستە", kmr: "یاریگەه هاتە پەسەندکرن و نوکە ل لێگەڕیانێ بەردەستە", ar: "تمت الموافقة على الملعب وأصبح متاحًا الآن في البحث" },
  "Pin the court location": { ckb: "شوێنی یاریگاکە دیاری بکە", kmr: "جهێ یاریگەهێ دیار بکە", ar: "حدّد موقع الملعب" },
  "Place the pin at the main entrance so players can arrive easily.": { ckb: "دەرزییەکە لە دەروازەی سەرەکی دابنێ بۆ ئەوەی یاریزانان بە ئاسانی بگەن.", kmr: "نیشانکێ ل دەرگەهێ سەرەکی دابنە دا یاریزان ب ساناهی بگەهن.", ar: "ضع الدبوس عند المدخل الرئيسي ليسهل على اللاعبين الوصول." },
